using System.Diagnostics;
using System.Net;
using System.Net.Sockets;
using UltimateArena.Core;
namespace UltimateArena.Network;
internal sealed class MatchClient:IDisposable {
    private readonly UdpClient socket;private bool disposed;private readonly IPEndPoint server;private readonly string name;private readonly Stopwatch clock=Stopwatch.StartNew();private double hello=-1,pingAt,lastHeard;private ulong token;private uint sequence,lastActors,lastProjectiles,buildActors,buildShots,lastEvent;private byte actorParts,shotParts;private readonly Dictionary<byte,List<Fighter>> actors=[];private readonly Dictionary<byte,List<Projectile>> shots=[];private readonly List<InputState> pending=[];
    public World World=new(1701,0);public Fighter? Predicted;public int Id,Ping;public string Status="CONNECTING";public bool Connected=>Id!=0&&clock.Elapsed.TotalSeconds-lastHeard<5;public readonly List<GameEvent> Received=[];
    public MatchClient(string address,string name){this.name=name;var parts=address.Split(':');int port=parts.Length>1?int.Parse(parts[1]):27960;if(port<1||port>65535)throw new ArgumentException("Port must be 1-65535.");var ip=Dns.GetHostAddresses(parts[0]).FirstOrDefault(p=>p.AddressFamily==AddressFamily.InterNetwork)??throw new ArgumentException("IPv4 address not found.");server=new(ip,port);socket=new UdpClient(new IPEndPoint(IPAddress.Any,0));socket.Client.Blocking=false;if(OperatingSystem.IsWindows()){try{socket.Client.IOControl(unchecked((int)0x9800000C),new byte[4],null);}catch(SocketException){}}}
    private void Send(BinaryWriter w){var b=Wire.Bytes(w);try{socket.Send(b,b.Length,server);}catch(SocketException){Status="NETWORK ERROR";}}
    public void Input(InputState input){if(!Connected)return;input.Sequence=++sequence;var w=Wire.Create(Packet.Input,token);Wire.Input(w,input);Send(w);pending.Add(input);if(pending.Count>120)pending.RemoveAt(0);if(Predicted!=null){Predicted.Yaw=input.Yaw;Predicted.Pitch=input.Pitch;Predicted.Weapon=input.Weapon;Movement.Step(Predicted,input,Core.World.Tick);}}
    public void Pump(){double now=clock.Elapsed.TotalSeconds;if(Id==0&&now-hello>.5){hello=now;var w=Wire.Create(Packet.Hello);Wire.Name(w,name);Send(w);}if(Connected&&now-pingAt>1){pingAt=now;var w=Wire.Create(Packet.Ping,token);w.Write(Stopwatch.GetTimestamp());Send(w);}if(Id!=0&&!Connected)Status="HOST TIMED OUT";else if(Id==0&&now>8)Status="NO HOST RESPONSE - CHECK ADDRESS AND UDP PORT";
        for(int n=0;n<256&&DataWaiting();n++){IPEndPoint endpoint=new(IPAddress.Any,0);byte[] bytes;try{bytes=socket.Receive(ref endpoint);}catch(SocketException){break;}if(!endpoint.Equals(server))continue;using var r=Wire.Open(bytes,out var type,out var packetToken);if(r==null)continue;try{if(type==Packet.Welcome){if(Id==0){Id=r.ReadInt32();token=packetToken;lastHeard=now;Status="CONNECTED";}continue;}if(Id==0||packetToken!=token)continue;lastHeard=now;Status="CONNECTED";
                if(type==Packet.Pong)Ping=(int)((Stopwatch.GetTimestamp()-r.ReadInt64())*1000/Stopwatch.Frequency);
                else if(type==Packet.Actors){uint seq=r.ReadUInt32();byte part=r.ReadByte(),parts=r.ReadByte();if(seq<=lastActors||parts==0||parts>3||part>=parts)continue;if(seq!=buildActors){buildActors=seq;actors.Clear();actorParts=parts;}float time=r.ReadSingle(),round=r.ReadSingle(),restart=r.ReadSingle();string winner=Wire.Name(r);var ready=new float[World.Pickups.Count];for(int i=0;i<ready.Length;i++)ready[i]=r.ReadSingle();int count=r.ReadByte();if(count>8)continue;var list=new List<Fighter>();for(int i=0;i<count;i++)list.Add(Wire.Fighter(r));actors[part]=list;if(actors.Count==actorParts){World.Fighters=actors.OrderBy(x=>x.Key).SelectMany(x=>x.Value).ToList();World.Time=time;World.RoundTime=round;World.Restart=restart;World.Winner=winner;for(int i=0;i<ready.Length;i++)World.Pickups[i].Ready=ready[i];lastActors=seq;var p=World.Fighters.Find(p=>p.Id==Id);if(p!=null){Predicted=p.Copy();pending.RemoveAll(i=>i.Sequence<=p.LastSequence);foreach(var input in pending){Predicted.Yaw=input.Yaw;Predicted.Pitch=input.Pitch;Movement.Step(Predicted,input,Core.World.Tick);}}}}
                else if(type==Packet.Projectiles){uint seq=r.ReadUInt32();byte part=r.ReadByte(),parts=r.ReadByte();if(seq<=lastProjectiles||parts==0||parts>4||part>=parts)continue;if(buildShots!=seq){buildShots=seq;shots.Clear();shotParts=parts;}int count=r.ReadByte();if(count>16)continue;var list=new List<Projectile>();for(int i=0;i<count;i++){var p=new Projectile{Id=r.ReadInt32(),Owner=r.ReadUInt16(),Weapon=r.ReadByte(),Position=Wire.Vector(r),Velocity=Wire.Vector(r)};byte flags=r.ReadByte();p.Sticky=(flags&1)!=0;p.Homing=(flags&2)!=0;p.Stuck=(flags&4)!=0;list.Add(p);}shots[part]=list;if(shots.Count==shotParts){World.Projectiles=shots.OrderBy(x=>x.Key).SelectMany(x=>x.Value).ToList();lastProjectiles=seq;}}
                else if(type==Packet.Events){int count=r.ReadByte();if(count>24)continue;for(int i=0;i<count;i++){var e=Wire.Event(r);if(e.Id>lastEvent){Received.Add(e);lastEvent=e.Id;}}}
            }catch(Exception ex)when(ex is EndOfStreamException or InvalidDataException or ArgumentException){}}
    }
    private bool DataWaiting(){try{return socket.Available>0;}catch(SocketException){return false;}}
    public void Dispose(){if(disposed)return;disposed=true;if(Id!=0){var w=Wire.Create(Packet.Leave,token);Send(w);}socket.Dispose();}
}
